SELECT eo.id AS opportunity_id, eo.symbol, eo.execution_source, eo.five_minute_decision, eo.executed_at, s1.id AS one_id, s1.candle_open_time AS one_candle, s1.generated_at AS one_generated, s5.id AS five_id, s5.decision AS five_decision, s5.original_decision AS five_original, s5.generated_at AS five_generated, pp.id AS paper_id, pp.status, pp.realized_pnl FROM crypto_ai.execution_opportunity eo JOIN crypto_ai.trade_signal s1 ON s1.id = eo.latest_signal_id AND s1.interval_code = '1m' JOIN crypto_ai.trade_signal s5 ON s5.symbol = s1.symbol AND s5.interval_code = '5m' AND s5.candle_open_time = s1.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN crypto_ai.paper_position pp ON pp.signal_id = s1.id WHERE eo.status = 'EXECUTED' AND MOD(MINUTE(s1.candle_open_time), 5) = 4 AND s5.generated_at > s1.generated_at ORDER BY eo.executed_at LIMIT 200